begin;set local statement_timeout='45s';set local lock_timeout='35s';set local application_name='start-control-proof';select set_config('request.jwt.claim.sub','a5100000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claim.role','service_role',true);select set_config('request.jwt.claims','{"role":"service_role"}',true);update private.quiz_start_control set paused=true,changed_at=clock_timestamp() where singleton;do $observe$ declare proof jsonb;finish timestamptz:=clock_timestamp()+interval '25 seconds';begin loop perform pg_stat_clear_snapshot();select jsonb_build_object('aPid',pg_backend_pid(),'bPid',s.pid,'waitType',s.wait_event_type,'waitEvent',s.wait_event,'blockedBy',pg_blocking_pids(s.pid),'at',clock_timestamp()) into proof from pg_stat_activity s where s.pid<>pg_backend_pid() and s.query like '%begin_local_quiz_v1%' and s.wait_event_type='Lock' and pg_backend_pid()=any(pg_blocking_pids(s.pid)) limit 1;exit when proof is not null;if clock_timestamp()>finish then raise exception 'start_control_overlap_not_observed';end if;perform pg_sleep(0.1);end loop;perform set_config('start_control.proof',proof::text,true);end $observe$;select jsonb_build_object('proof',current_setting('start_control.proof')::jsonb,'paused',paused) value from private.quiz_start_control;commit;
